package cd.kinshasa.smartcity.flood.model; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="flood_alerts") public class FloodAlert{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public Long zoneId; public String message; @Enumerated(EnumType.STRING) public AlertLevel level=AlertLevel.INFO; public Instant date=Instant.now(); public boolean resolved=false; }
